mapper.select:
SELECT id, patient_name as patientName, patient_gender as patientGender, patient_age as patientAge, patient_id_card as patientIdCard, blood_pressure_systolic as bloodPressureSystolic, blood_pressure_diastolic as bloodPressureDiastolic, bmi, fasting_blood_glucose as fastingBloodGlucose, constitution_type as constitutionType, exam_date as examDate, create_time as createTime FROM health_exam
AND (patient_name LIKE CONCAT('%', #{keyword}, '%') OR patient_id_card LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY create_time DESC LIMIT #{offset}, #{limit}
